    end
    function self:draw()
        if not imgui.tree_node("背景变形 / Background###background") then return end
        imgui.text("进入场景后自动载入；开启总开关默认启用背景果冻。")
        if imgui.button("载入当前场景背景 / Load background###load_background") then self:request() end
        imgui.text(self.status)
