local throw_probe = __jamieswine_modules["throw_probe"]
local throw_shrink = __jamieswine_modules["throw_shrink"]
local config = __jamieswine_modules["config"]
local clock = __jamieswine_modules["clock"].new(os.clock)
local key_options = __jamieswine_modules["hotkeys"]
local hotkeys = key_options.new(function(key) return reframework:is_key_down(key) end)
